#!/usr/bin/env python3
"""A source-scoped connection pass; evaluation and documentary evidence stay distinct."""
from pathlib import Path
import json,re,html,hashlib
from apply_iteration_17 import enc,parse,upsert,source_record,node_record,profile_record,edge_record,relation_record
from apply_iteration_09 import graph_metrics
from apply_relational_depth_16 import calculate_relational_depth,write_relational_document
from apply_doncaster_lineage import refresh_counts
from refresh_graph_snapshot import calculate,write
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-09-09'
MARK='september_connections_2026'
BASE=json.loads((ROOT/'sources/september-2026/base-records.json').read_text())
def slug(x):return re.sub('[^a-z0-9]+','_',x.lower()).strip('_')
def source(d,key,title,url,notes,creators=(),publisher='',kind='primary_public_webpage'):
    s=source_record(key,title,kind,url,notes,list(creators),publisher,DATE,quality='B' if kind=='submitted_reading_recommendation' else 'A')
    s.update(last_checked=DATE,review_status='source_scope_checked',connection_pass=MARK);upsert(d['sources'],[s],'id');return key

def node(d,key,title,kind,summary,sids,tags=(),aliases=()):
    matches=[n for n in d['nodes'] if n['entity_type']==kind and (n['id']==key or n['label'].casefold()==title.casefold() or title.casefold() in [str(a).casefold() for a in parse(n.get('aliases'))])]
    if matches:
        key=d.get('canonical_redirects',{}).get(matches[0]['id'],matches[0]['id']);n=next(n for n in d['nodes'] if n['id']==key)
        if not any(x['id']==key for x in BASE['nodes']):BASE['nodes'].append(json.loads(json.dumps(n)))
        n['source_ids']=enc(list(dict.fromkeys(parse(n.get('source_ids'))+sids)));n['aliases']=enc(list(dict.fromkeys(parse(n.get('aliases'))+list(aliases))))
    else:
        v=int(hashlib.sha256(key.encode()).hexdigest()[:8],16)
        n=node_record(key,title,kind,summary,sids,(v%1000)/1000-.5,((v//1000)%1000)/1000-.5,list(tags),aliases=list(aliases),level='described')
        n.update(inclusion_reason=MARK,status='candidate',review_status='source_scoped_research_pass',reviewed_by='',reviewed_at='',set_tags=enc(list(tags)+[MARK]));d['nodes'].append(n)
    return key

def edge(d,a,b,typ,family,phrase,sids,locator,scope,mode='asserted'):
    if a==b:return
    key='e24_'+slug(a+'_'+typ+'_'+b)
    if any(e['source']==a and e['target']==b and e['relation_type']==typ and not e['id'].startswith('e24_') for e in d['edges']):return
    e=edge_record(key,a,b,typ,family,phrase,sids,locator,scope,status='candidate',mode=mode,confidence='',review_label='Located source statement; independent review not recorded' if mode=='asserted' else 'Editorial comparison; open to challenge')
    e.update(reviewed_by='',reviewed_at='');upsert(d['edges'],[e],'id')

def profile(d,nid,summary,why,distinctions,practices,sids,locator,limits):
    previous=next((p for p in d['profiles'] if p['node_id']==nid),None)
    if previous and not any(p['node_id']==nid for p in BASE['profiles']) and nid not in BASE.get('absent_profiles',[]):BASE['profiles'].append(json.loads(json.dumps(previous)))
    if not previous and nid not in BASE.setdefault('absent_profiles',[]):BASE['absent_profiles'].append(nid)
    p=profile_record(nid,summary,why,distinctions,[],[],[],practices,[],limits,sids,context=locator,editorial_note='Prepared with AI assistance from the specified sources. Publication is authorised; independent specialist review is not recorded. Practice implications are editorial applications.')
    p.update(title=next(n['label'] for n in d['nodes'] if n['id']==nid),last_researched=DATE,profile_status='source_scoped_research_pass',review_status='independent_review_not_recorded',reviewed_by='',reviewed_at='')
    upsert(d['profiles'],[p],'node_id');n=next(n for n in d['nodes'] if n['id']==nid);n.update(publication_level='profile',description=summary,canonical_definition=summary,public_stub_text='')

def page(path,title,body):
    p=ROOT/'docs'/path/'index.html';p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text('<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' | The Necessary Tangle</title><link rel="canonical" href="https://transduction.systems/'+path+'/"><style>body{font:18px/1.65 system-ui;color:#19272d;max-width:980px;margin:auto;padding:24px;background:#faf9f5}h1{line-height:1.15}a{color:#145d69;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #ccd5d8;padding:.7em}td:first-child{min-width:120px}nav{display:flex;gap:1em;flex-wrap:wrap}.note{padding:1em;background:#edf1ee} @media(max-width:650px){table,tbody,tr,td{display:block}thead{display:none}td{padding:.5em}}</style></head><body><nav><a href="/">Atlas</a><a href="/reading-list.html">Reading</a><a href="/systems-thinking/practice/">Practice</a><a href="/events/">Events</a><a href="/updates/">Updates</a></nav><main><h1>'+html.escape(title)+'</h1>'+body+'</main></body></html>\n')

def main():
    d=json.loads((ROOT/'data/public-data.json').read_text())
    for typ,family,phrase in [('offers_reading_route_to','documentary','offers a reading route to'),('implements_notation_for','practical','implements a notation for'),('depicts_coordination_in','conceptual','depicts coordination in'),('depicts_recursive_units_in','conceptual','depicts recursive units in'),('helps_identify','practical','helps identify'),('applies_principle','conceptual','applies the principle'),('introduces_distinction','conceptual','introduces the distinction'),('requires_authority_for','conceptual','requires authority for'),('compares_method','conceptual','compares the method'),('authored_by','documentary','is authored by'),('edited_by','documentary','is edited by'),('presents_account_of','conceptual','presents an account of'),('distinguishes_from','conceptual','distinguishes from')]:
        if not any(r['relation_type']==typ for r in d['relation_types']):upsert(d['relation_types'],[relation_record(typ,family,'inverse_'+typ,'A specified source passage or explicitly labelled editorial comparison',phrase)],'relation_type')
    rec=source(d,'src_ing_ocad_reading_recommendations_2026','David Ing: core readings for Understanding Systems','https://github.com/antlerboy/the-necessary-tangle/issues/2#issuecomment-5558769097','Publicly supplied reading recommendation, including the six core resources and the separate roles of instructor Stephen N. Davies and volunteer David Ing. This supports recommendation and role attribution, not a complete reading of the course.',['David Ing'],'The Necessary Tangle public intake','submitted_reading_recommendation')
    ocad=source(d,'src_ocad_sfin6011_pro_forma_2026','Understanding Systems: SFIN-6011 winter 2026 pro forma','https://coevolving.com/ocadu/202601-sfin-6011/pro-forma/Whole_2026_SFIN6011_pro-forma_v0101a.html','Primary course source supplied for close reading. Retrieval was unavailable on 9 September. No module-by-module contents or influence claims have been inferred.',['David Ing'],'Coevolving','course_source_pending_retrieval')
    route=node(d,'corpus_ing_ocad_reading_route_2026','Understanding Systems: Ing’s OCAD reading route','corpus','A guided entrance to the six resources identified in David Ing’s recommendation for the winter 2026 OCAD course. The complete 13-week pro forma remains a separate source-reading task.',[rec,ocad],['education','systems'])
    sources=[];works=[]
    bibli=[
      ('coping_complexity','Tools, Exercises, and Strategies for Coping With Complexity','https://www.igi-global.com/book/tools-exercises-strategies-coping-complexity/302472','R. Storesund; Ian I. Mitroff','IGI Global','Publication metadata and the submitted reading recommendation checked; full text not reviewed.','publication'),
      ('systems_thinker_archive','The Systems Thinker','https://thesystemsthinker.com/about/','The Systems Thinker','Leverage Networks','Publisher’s About page and the submitted reading recommendation. An archive of multiple authors, not one authored theory.','corpus'),
      ('systems_approaches_change_2020','Systems Approaches to Making Change: A Practical Guide','https://link.springer.com/book/10.1007/978-1-4471-7472-1','Martin Reynolds; Sue Holwell','Springer','Second edition, 2020. Publisher metadata checked; the introductory chapter abstract provides a bounded comparison of five methods.','publication'),
      ('systems_thinkers_ramage_shipp','Systems Thinkers','https://link.springer.com/book/10.1007/978-1-4471-7475-2','Magnus Ramage; Karen Shipp','Springer','Second edition, 2020. Ramage and Shipp are credited by the publisher as authors.','publication'),
      ('contexts_journal','Contexts: The Systemic Design Journal','https://systemic-design.org/contexts/','Systemic Design Association','Systemic Design Association','Journal named in the submitted recommendation. Article-level review remains open.','corpus'),
      ('she_ji_journal','She Ji: The Journal of Design, Economics, and Innovation','https://www.sciencedirect.com/journal/she-ji-the-journal-of-design-economics-and-innovation','Tongji University','Tongji University / Elsevier','Journal named in the submitted recommendation. Article-level review remains open.','corpus')]
    for key,title,url,creators,publisher,notes,kind in bibli:
        sid=source(d,'src_sep_'+key,title,url,notes,creators.split('; '),publisher,'publisher_record' if 'springer' in url or 'igi-' in url else 'resource_metadata')
        nid=node(d,('publication_' if kind=='publication' else 'corpus_')+key,title,kind,notes,[sid,rec],['reading','systems']);works.append(nid);sources.append(sid)
        edge(d,route,nid,'offers_reading_route_to','documentary','offers a reading route to',[rec],'Six-item core reading recommendation','Selection for teaching. No intellectual influence, equivalence, or approval of every claim is inferred.')
    for nid,people,sid,typ in [(works[0],[('person_r_storesund','R. Storesund'),('person_ian_i_mitroff','Ian I. Mitroff')],sources[0],'authored_by'),(works[2],[('person_martin_reynolds','Martin Reynolds'),('person_sue_holwell','Sue Holwell')],sources[2],'edited_by'),(works[3],[('person_magnus_ramage','Magnus Ramage'),('person_karen_shipp','Karen Shipp')],sources[3],'authored_by')]:
        for key,label in people:
            person=node(d,key,label,'person','Credited '+('editor' if typ=='edited_by' else 'author')+' of '+next(n['label'] for n in d['nodes'] if n['id']==nid)+'.',[sid],['systems','writing'])
            edge(d,nid,person,typ,'documentary','is edited by' if typ=='edited_by' else 'is authored by',[sid],'Publisher author/editor metadata','Bibliographic credit only.')
    chapter=source(d,'src_reynolds_holwell_intro_2020','Introducing Systems Approaches','https://link.springer.com/chapter/10.1007/978-1-4471-7472-1_1','Abstract and publisher bibliographic record inspected. Full chapter is subscription content and was not reviewed.',['Martin Reynolds','Sue Holwell'],'Springer','primary_chapter_abstract')
    intro=node(d,'publication_reynolds_holwell_intro_2020','Introducing Systems Approaches (2020)','publication','The introductory chapter compares SD, VSM, SODA, SSM and CSH through their use in situations of change, constructivist potential and adaptability in combinations.',[chapter],['methodology'])
    for suffix in ['system_dynamics','viable_system_model_vsm','strategic_options_development_and_analysis_soda','soft_systems_methodology_ssm','critical_systems_heuristics_csh']:
        edge(d,intro,'method_or_methodology_'+suffix,'compares_method','conceptual','compares the method',[chapter],'Chapter abstract, pp. 1–24 record','The abstract supports the authors’ stated comparative rationale. It does not establish that the methods are interchangeable or that the whole chapter was read.')
    edge(d,works[2],intro,'offers_reading_route_to','documentary','offers a reading route to',[chapter],'Book title and chapter record','Part-to-whole reading route only.')
    # FEM: scope each statement to the author’s explicit use, rather than making VSM a synonym for FEM.
    femid='intervention_skill_fractal_enterprise_model_and_capabilities'
    fs=source(d,'src_fem_toolkit_2026','FEM toolkit 1.3','https://fractalmodel.blogs.dsv.su.se/fem-toolkit/','Official toolkit page inspected. It lists Windows, Linux and Mac installers and explains the Windows code and virtualisation. Installer availability is not a platform compatibility test.',['Fractal Enterprise Model project'],'Stockholm University project site')
    f2=source(d,'src_fem_vsm_system2','System 2 of VSM through the lens of FEM','https://fractalmodel.blogs.dsv.su.se/vsms2fem/','Inspected the explanatory text: FEM patterns depict coordination needs and possible System 2 arrangements. The project’s criticism of VSM visual notation is its own assessment.',['Fractal Enterprise Model project'],'Stockholm University project site')
    f1=source(d,'src_fem_vsm_system1','Decomposition of System 1 units of VSM','https://fractalmodel.blogs.dsv.su.se/vsm-s1-decomposition/','Inspected text on responsibilities, process/asset boundaries, ghosts and groups. Decomposition may denote variants or parts, which must be distinguished.',['Fractal Enterprise Model project'],'Stockholm University project site')
    fc=source(d,'src_fem_structural_coupling','Structural coupling through FEM','https://fractalmodel.blogs.dsv.su.se/structural-coupling-2/','Inspected project account of identifying enterprise-environment couplings. It attributes the term to Maturana and Varela and cites Hoverstadt’s strategy application; those historical claims remain attributed.',['Fractal Enterprise Model project'],'Stockholm University project site')
    toolkit=node(d,'tool_fem_toolkit','FEM toolkit','tool','A diagramming tool for Fractal Enterprise Models. Version 1.3 is listed with three operating-system installers; installation has not been independently tested in this pass.',[fs],['enterprise','modelling'])
    coupling=node(d,'concept_structural_coupling','Structural coupling','concept','Repeated system-environment interaction can shape the structures through which further interaction occurs. The FEM project uses this idea to identify consequential enterprise-environment relationships; that application is narrower than the biological concept.',[fc],['cybernetics'])
    edge(d,toolkit,femid,'implements_notation_for','practical','implements a notation for',[fs],'Toolkit introduction','Tool support; no claim of independent compatibility testing.')
    vsm='method_or_methodology_viable_system_model_vsm'
    edge(d,femid,vsm,'depicts_coordination_in','conceptual','depicts coordination in',[f2],'Opening text and System 2 pattern description','A modelling application to System 2, not a replacement of the entire VSM.')
    edge(d,femid,vsm,'depicts_recursive_units_in','conceptual','depicts recursive units in',[f1],'Responsibility, ghosts and groups paragraphs','System 1 process and asset decomposition; distinctions between parts and variants remain necessary.')
    edge(d,femid,coupling,'helps_identify','practical','helps identify',[fc],'Final explanatory paragraph and higher-education example','The author’s proposed enterprise-modelling use. No proof that every structural coupling will be found.')
    profile(d,femid,'Fractal Enterprise Model connects business processes and the assets they use and maintain. The project shows how its notation can represent VSM coordination, recursive operational units and selected enterprise-environment relationships.','The diagrams offer a way to inspect concrete processes, assets and responsibilities when a generic organisational model is too coarse.',['FEM notation is distinct from the VSM’s account of viability.','Decomposing a model into variants is distinct from decomposing it into parts.','An installer download is distinct from a tested installation.'],['Inspect which processes use or maintain an asset.','Use the System 2 and System 1 examples to question coordination and responsibility.'],[fs,f2,f1,fc],'Official toolkit and three linked application pages.',['Independent validation of the modelling claims remains open.','Platform compatibility has not been tested.'])
    # Taylor and Boxer: a public working paper with versioned, page-specific evidence.
    ps=source(d,'src_taylor_boxer_boundary_2026','What the boundary cannot carry alone, working redraft v3','https://antlerboy.com/library/what-the-boundary-cannot-carry-alone/','Taylor and Boxer, 26 August 2026. All seven pages of the supplied manuscript inspected; not a peer-reviewed final article. The title page gives v3; the running footer retains v1.',['Benjamin P Taylor','Philip Boxer'],'Benjamin P Taylor public work library','working_paper')
    paper=node(d,'publication_boundary_cannot_carry_alone','What the boundary cannot carry alone','publication','Taylor and Boxer’s working paper distinguishes form of response from scope of holding and proposes organisational conditions that can sustain relational public services.',[ps],['public-services','relational'])
    ben=node(d,'person_benjamin_p_taylor','Benjamin P Taylor','person','Systems practitioner and educator, and co-author with Philip Boxer of What the boundary cannot carry alone. This entry starts from inspectable public work and does not claim a complete account of his contributions.',[ps],['public-services','practice'],['Benjamin Taylor','Benjamin P. Taylor','antlerboy'])
    boxer='person_philip_boxer'
    for author in [ben,boxer]:edge(d,paper,author,'authored_by','documentary','is authored by',[ps],'Title page, p. 1','Author order: Benjamin P Taylor, then Philip Boxer.')
    terms=[('form_of_response','Form of response (relational public services)','The paper’s axis for how far a citizen’s situation can reshape an institutional response, from a fixed frame towards a response that can revise the task.'),('scope_of_holding','Scope of holding (relational public services)','The paper’s axis for where sense-making, capability, uncertainty, resources and risk are carried: encounter, service, system conditions, place or citizen association.'),('strategy_ceiling','Strategy ceiling (Taylor and Boxer)','The point above which learning from an encounter cannot alter the rules, resources, measures or institutional choices shaping it.'),('consequential_learning','Consequential learning (relational public services)','Learning that can change the rules, resources, task or boundary of public-service work, instead of remaining a local reflection without an institutional response.')]
    ids=[]
    for key,title,summary in terms:
        nid=node(d,'concept_'+key,title,'concept',summary,[ps],['public-services','relational']);ids.append(nid)
        edge(d,paper,nid,'introduces_distinction','conceptual','introduces the distinction',[ps],'pp. 2–5; Figure 1 and Table 2','A practitioner proposition in this specific working paper, not an independently validated instrument.')
    edge(d,ids[0],ids[1],'distinguishes_from','conceptual','distinguishes from',[ps],'pp. 2–3, Figure 1','Position, health and fit are separate judgements; a wider scope is not automatically better.')
    edge(d,paper,'concept_requisite_variety','applies_principle','conceptual','applies the principle',[ps],'p. 2, paragraph following Table 1','Variety of response relative to demand; the paper also questions whether the task boundary itself is adequate.')
    edge(d,paper,vsm,'applies_principle','conceptual','applies the governance account in',[ps],'p. 5, Governance and consequential learning; Beer 1979 and Espejo/Reyes 2011 references','An application of organisational governance and identity revision; not validation of the whole proposed diagnostic.')
    edge(d,ids[2],ids[3],'requires_authority_for','conceptual','requires authority for',[ps],'p. 4, Strategy ceiling; p. 5, Governance and consequential learning','Crossing the ceiling requires a route by which evidence can change institutional conditions.')
    profile(d,paper,'A relational encounter can improve while the organisation behind it remains unchanged. Taylor and Boxer distinguish form of response, scope of holding, health and fit, then propose four organisational conditions for sustaining relational public services.','It makes the organisational demands behind relational practice explicit, including what evidence must be able to change.',['Form of response differs from scope of holding.','A wider scope is not necessarily healthier or better fitted to demand.','Relational behaviour differs from authority to revise rules and resources.'],['Start with actual demand in citizens’ words.','Ask who carries the work and risk, and what happens to learning.'],[ps],'Working redraft v3, pp. 1–7; Figure 1 and Tables 1–2.',['The authors describe a practitioner proposition, not a validated instrument.','Title-page v3 is retained; the source’s running footer still says v1.'])
    # A bounded pass on new people/organisation submissions, using located primary records.
