    handbook=node(d,'publication_handbook_systems_sciences_2021','Handbook of Systems Sciences','publication','The 2021 handbook edited by Metcalf, Kijima and Deguchi presents relationships between systems theories and their use in modelling and practice.',[hs],['systems','reference'])
    for key,label,aliases in [('person_gary_s_metcalf','Gary S. Metcalf',['Gary Metcalf']),('person_kyoichi_kijima','Kyoichi Kijima',['Kyoichi (Jim) Kijima','Jim Kijima']),('person_hiroshi_deguchi','Hiroshi Deguchi',[])]:
        nid=node(d,key,label,'person','Co-editor of the 2021 Handbook of Systems Sciences. This initial entry records the publisher-verified contribution; a fuller intellectual profile remains open.',[hs],['systems'],aliases)
        edge(d,handbook,nid,'edited_by','documentary','is edited by',[hs],'Editors and bibliographic information','Role in this volume; no claim about relative influence or current institutional office.')
    orgs=source(d,'src_ifsr_isss_member_2026','ISSS: IFSR member record','https://ifsr.org/member/international-society-for-the-systems-sciences-isss/','IFSR member page inspected: interdisciplinary inquiry, society name history and practical exchange. Membership supports a specific institutional connection, not consensus across the field.',['IFSR'],'IFSR','institutional_record')
    isss=node(d,'organisation_isss','International Society for the Systems Sciences','organisation','An interdisciplinary systems-sciences society, previously named the Society for General Systems Research. Its IFSR member record describes both theoretical inquiry and exchange among practitioners.',[orgs],['systems'],['ISSS','Society for General Systems Research'])
    ifsr=node(d,'organisation_ifsr','International Federation for Systems Research','organisation','A federation connecting systems-research organisations. The linked member record establishes its relationship with ISSS; broader institutional history remains a separate research task.',[orgs],['systems'],['IFSR'])
