    edge(d,'person_gerald_midgley',isss,'held_role_in','institutional','held the 2013/14 presidency of',[ms],'Biographical paragraph: 2013/14 President','Historical role, not a statement about the current presidency.')
    if not any(r['relation_type']=='held_role_in' for r in d['relation_types']):upsert(d['relation_types'],[relation_record('held_role_in','institutional','had_role_holder','Dated institutional biography','held a specified role in')],'relation_type')
    ts=source(d,'src_trist_palgrave_2017','Eric Trist: An American/North American View','https://link.springer.com/referenceworkentry/10.1007/978-3-319-49820-1_27-1','Abstract and bibliographic metadata inspected; full subscription chapter not reviewed. The abstract discusses sociotechnical systems, organisation design, action research and work with Fred Emery.',[],'Springer / Palgrave','chapter_abstract')
    node(d,'person_eric_trist','Eric Trist','person','Eric Lansdown Trist (1909–1993) worked on sociotechnical systems and organisation design. The cited chapter abstract also describes action research and his work with Fred Emery.',[ts],['sociotechnical','organisation'],['Eric L. Trist','Eric Lansdown Trist'])
    rs=source(d,'src_robert_rosen_archive_2026','Robert Rosen scientific-work archive','https://www.rosenlife.org/','Archive landing page inspected; identifies Rosen as a biologist and provides routes into the scientific-work collection. Detailed theoretical claims in the submission remain unreviewed.',['Robert Rosen archive'],'Rosenlife','author_archive')
    node(d,'person_robert_rosen','Robert Rosen','person','A biologist whose archive provides access to work across biology, complexity, mathematics and epistemology. This entry identifies the collection; the submitted claims about anticipatory systems require a separate close-reading pass.',[rs],['biology','systems'])
    # Remove an unowned evaluative sentence; avoid asserting a named human review of this revision.
    p=next(p for p in d['profiles'] if p['node_id']=='person_david_ing')
    p['common_misreadings']=enc(['Documented association is not by itself evidence of intellectual influence.'])
    p['summary']='Ing’s public work includes service-systems research, systems-changes learning, teaching and documentation of systems scholarship. The linked source records identify the basis and limits of this account.'
    p.update(review_status='source_scoped_research_pass',profile_status='source_scoped_research_pass',reviewed_by='',reviewed_at='',editorial_note='This account and its framing were prepared with AI assistance. The source records support documentary claims; evaluative and practice interpretations are editorial and open to challenge. No new independent review or contributor role is implied.',last_researched=DATE)
    # Both public curriculum versions remain visible; teaching order is not an influence claim.
    curriculum=json.loads((ROOT/'sources/september-2026/leading-transformation.json').read_text())
    curriculum_nodes=[]
    for version,filename in [('original','leading-transformation.json'),('revised','curriculum-2026.json')]:
        sid=source(d,'src_sep_lt_'+version,'Leading Transformation: '+curriculum[version]['label'],'https://github.com/antlerboy/PSTA/blob/main/content/'+filename,'Public programme module register inspected. This is an educational route, not evidence of an intellectual lineage or a delivery commitment.',['RedQuadrant','Public Service Transformation Academy'],'Public Service Transformation Academy','public_curriculum')
        nid=node(d,'corpus_leading_transformation_'+version,'Leading Transformation: '+curriculum[version]['label'],'corpus','A 24-module learning architecture for public-service transformation. Both this version and the other dated version remain available for comparison.',[sid],['education','practice','public-services']);curriculum_nodes.append(nid)
        for target,locator in [('method_or_methodology_viable_system_model_vsm','Original modules 3 and 8; revised module 17'),('intervention_skill_lean_and_six_sigma','Original module 16; revised module 13: Lean component only, not Six Sigma'),('method_or_methodology_patterns_of_strategy','Original module 23; revised module 21'),('intervention_skill_appreciative_inquiry','Original module 21; revised module 23')]:
            edge(d,nid,target,'offers_reading_route_to','documentary','offers a learning route to',[sid],locator,'The module summary names this approach. Selection for practice does not establish theoretical equivalence, intellectual influence or effectiveness.')
